head.script:
scwin.onpageload = function() {
	var submissionObj = {
		"id": "submission_dynamic0",
		"ref": "data:json,dc_reqDataMap",
		"target": "data:json,dc_resDataMap",
		"action": "/data/widgetContainer_processMsgFrame_WESD-1309_(WSQ-5292)_jsonData10000.json",
		"method": "post",
		"mediatype": "application/json",
		"encoding": "UTF-8",
		"mode": "asynchronous",
		"processMsg": "processing ~ ~ ~ ",
		"submitErrorHandler": function(e) {
			alert(e.responseStatusCode);
		}
	};
	$p.createSubmission(submissionObj);
};

scwin.trigger1_onclick = function(e) {
	WebSquare.ModelUtil.executeSubmission("submission_dynamic0");
};
